int main(int argc,char**argv){@autoreleasepool{if(argc!=2)return 1;NSImage*i=[[NSImage alloc]initWithSize:NSMakeSize(512,512)];[i lockFocus];[[NSColor colorWithSRGBRed:.10 green:.30 blue:.25 alpha:1]setFill];[[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(16,16,480,480) xRadius:100 yRadius:100]fill];NSDictionary*a=@{NSFontAttributeName:[NSFont boldSystemFontOfSize:145],NSForegroundColorAttributeName:NSColor.whiteColor};[@"LKK" drawAtPoint:NSMakePoint(84,165) withAttributes:a];[i unlockFocus];NSBitmapImageRep*b=[NSBitmapImageRep imageRepWithData:i.TIFFRepresentation];NSData*d=[b representationUsingType:NSBitmapImageFileTypePNG properties:@{}];return [d writeToFile:[NSString stringWithUTF8String:argv[1]] atomically:YES]?0:1;}}
